mapper.select:
SELECT a.*, u.username, ad.username AS admin_name, p.type AS punish_type, p.reason AS punish_reason FROM appeal a LEFT JOIN user u ON a.user_id = u.user_id LEFT JOIN user ad ON a.review_admin = ad.user_id LEFT JOIN punishment p ON a.punish_id = p.punish_id
AND a.status = #{status}
ORDER BY a.appeal_id DESC
